reference.PrefixMaxima:
p := [];
var w: seq<int> := [];
var i := 0;
while i < |s|
  invariant 0 <= i <= |s|
  invariant |p| == i
  invariant |w| == i
  invariant forall k :: 0 <= k < i ==> 0 <= w[k] <= k && p[k] == s[w[k]]
  invariant forall k, j :: 0 <= j <= k < i ==> s[j] <= p[k]
  invariant forall k :: 0 <= k < i ==> exists j :: 0 <= j <= k && p[k] == s[j]
  decreases |s| - i
{
  var m := s[i];
  var q := i;
  if i > 0 && p[i-1] > m {
    m := p[i-1];
    q := w[i-1];
  }
  assert forall j :: 0 <= j <= i ==> s[j] <= m;
  assert exists j :: 0 <= j <= i && m == s[j];
  p := p + [m];
  w := w + [q];
  i := i + 1;
}
assert forall k :: 0 <= k < |s| ==> exists j :: j == w[k] && 0 <= j <= k && p[k] == s[j];

bodies.PrefixMaxima:
p := [];
var i := 0;
var m := 0;
while i < |s|
  invariant 0 <= i <= |s|
  decreases |s| - i
{
  if s[i] < m {
    m := s[i];
  }
  p := p + [m];
  i := i + 1;
}
